import json,os,pathlib,subprocess,time
ROOT=pathlib.Path('/private/tmp/goway-stage11-rc30578f82-laneC5');OUT=ROOT/'profiles';OUT.mkdir(exist_ok=False)
TREES={'baseline':pathlib.Path('/Users/weiloon/Projects/rust-go/Foundry-Go-measure-main'),'branch':pathlib.Path('/Users/weiloon/Projects/rust-go/Foundry-Go-goway-laneC5'),'pre4a':pathlib.Path('/Users/weiloon/Projects/rust-go/Foundry-Go-measure-pre4a')}
cases=[('stage6-build','stage6-session2','^BenchmarkChainBuild$','3s',False)]
records=[]
for label,session,bench,duration,exact_memory in cases:
 for side in ('baseline','branch'):
  name=label+'-'+side;binary=ROOT/session/(side+'.test');directory=OUT/name;directory.mkdir()
  tree=TREES['pre4a' if side=='baseline' and session.startswith('stage6') else side]
  cwd=tree/('tests/fixtures/goway' if session.startswith('stage6') else 'tests/fixtures/consumer')
  cmd=[str(binary),'-test.timeout=5m','-test.run=^$','-test.bench='+bench,'-test.benchmem','-test.benchtime='+duration,'-test.count=1','-test.memprofile='+str(directory/'alloc.pprof')]
  if exact_memory:cmd+=['-test.memprofilerate=1']
  else:cmd+=['-test.cpuprofile='+str(directory/'cpu.pprof')]
  before=os.getloadavg();started=time.monotonic()
  with (directory/'benchmark.log').open('wb') as out:done=subprocess.run(cmd,cwd=cwd,stdout=out,stderr=subprocess.STDOUT,timeout=300)
  record={'name':name,'purpose':'diagnostic only; excluded from acceptance benchmark samples','command':cmd,'exit':done.returncode,'seconds':time.monotonic()-started,'load_before':before,'load_after':os.getloadavg()}
  records.append(record);(OUT/'profiles.json').write_text(json.dumps(records,indent=2)+'\n')
  if done.returncode:raise RuntimeError('profile failed: '+name)
  for metric,profile in [('alloc_objects','alloc.pprof')]+([] if exact_memory else [('cpu','cpu.pprof')]):
   cmd=['go','tool','pprof','-top','-nodecount=35']+(['-alloc_objects'] if metric=='alloc_objects' else [])+[str(binary),str(directory/profile)]
   with (directory/(metric+'-top.txt')).open('wb') as out:done=subprocess.run(cmd,cwd=cwd,stdout=out,stderr=subprocess.STDOUT,timeout=120)
   if done.returncode:raise RuntimeError('pprof failed: '+name)
  print('Profile recorded:',name,flush=True)

